namespace Lastlight.Core;
public sealed partial class World
{
 public void ValidateRegion(Definitions d)
 {
  var r=Region;if(r==null||!r.Initialized||r.RandomState==0||r.NextId<1||r.ObservedDangerTick< -1||r.ObservedDangerTick>Tick||r.ObservedCraftTick< -1||r.ObservedCraftTick>Tick||r.LastDay<0||r.LastDay>Tick/TicksPerDay||r.Tiles==null||r.Factions==null||r.People==null||r.Sites==null||r.Artifacts==null||r.History==null||r.Parties==null||r.Treaties==null||r.Quests==null||r.Traders==null||r.Absent==null||r.RecordedDeaths==null||r.History.Count>256||r.Parties.Count>32||r.Traders.Count>24||r.ArtifactTransfers<0||r.TradeTransactions<0)throw new InvalidDataException("Invalid living region state.");if(!r.Enabled)return;
  if(r.Width!=12||r.Height!=12||r.Tiles.Count!=144||r.Factions.Count!=6||r.Sites.Count is <13 or >14||!r.Sites.Any(s=>s.Id==r.HomeSiteId&&s.Kind=="Colony"))throw new InvalidDataException("Invalid regional geography.");
  bool Cell(int i)=>i>=0&&i<Cells.Count;bool Faction(long id)=>id==0||r.Factions.Any(f=>f.Id==id);bool Site(long id)=>id==0||r.Sites.Any(s=>s.Id==id);bool Artifact(long id)=>id==0||r.Artifacts.Any(a=>a.Id==id);var ids=new HashSet<long>();void Id(long id){if(id<1||id>=r.NextId||!ids.Add(id))throw new InvalidDataException("Invalid/duplicate regional identity.");}bool Cargo(Dictionary<string,int> cargo)=>cargo!=null&&cargo.All(k=>d.Entities.TryGetValue(k.Key,out var e)&&e.Kind==EntityKind.ItemStack&&k.Value is >=0 and <=10000);
  foreach(var tile in r.Tiles)if(tile==null||tile.X<0||tile.X>=12||tile.Y<0||tile.Y>=12||tile.Height is <0 or >99||tile.Climate is < -10 or >49||tile.Culture is <1 or >6||tile.Terrain is not ("Steppe" or "Highlands" or "Wetland"))throw new InvalidDataException("Invalid region tile.");if(r.Tiles.Select(t=>(t.X,t.Y)).Distinct().Count()!=144)throw new InvalidDataException("Duplicate regional tile.");
  foreach(var f in r.Factions){Id(f.Id);if(f.Name==null||f.Name.Length>100||f.Population is <1 or >10000||f.Strength is <0 or >1000||f.Goodwill is < -100 or >100||f.Trust is < -100 or >100||f.Compatibility is < -100 or >100||f.Grievance is <0 or >100||!Cargo(f.Reserves)||f.Claims==null)throw new InvalidDataException("Invalid faction economy/relations.");}
  foreach(var p in r.People){Id(p.Id);if(!Faction(p.FactionId)||p.Name==null||p.Born>100||p.Died!=0&&p.Died<p.Born)throw new InvalidDataException("Invalid historical person.");}
  foreach(var s in r.Sites){Id(s.Id);if(!Faction(s.FactionId)||s.X<0||s.X>=12||s.Y<0||s.Y>=12||s.Slot is <0 or >13||s.Name==null||s.HistoryTag==null||s.EntityIds==null||s.EntityIds.Any(id=>id<1||id>=NextEntityId)||s.Instantiated&&(!Cell(s.AnchorCell)||s.MarketId!=0&&Find(s.MarketId)==null)||s.GuardianId<0||s.GuardianId>=NextEntityId)throw new InvalidDataException("Invalid region site.");}
  foreach(var a in r.Artifacts){Id(a.Id);if(!Site(a.SiteId)||!Faction(a.OwnerFactionId)||!d.Entities.ContainsKey(a.DefinitionId)||a.Custody is not ("Site" or "Party" or "Colony" or "Faction" or "Lost")||a.LocalEntityId<0||a.LocalEntityId>=NextEntityId||a.Custody=="Party"&&!r.Parties.Any(p=>p.Id==a.PartyId&&p.Artifacts.Contains(a.Id))||a.Custody=="Colony"&&Find(a.LocalEntityId)==null||a.Custody=="Site"&&r.Sites.First(s=>s.Id==a.SiteId).Instantiated&&Find(a.LocalEntityId)==null)throw new InvalidDataException("Invalid unique artifact custody.");}
  var activeMembers=new HashSet<long>();var absent=new HashSet<long>();foreach(var p in r.Parties){Id(p.Id);if(!Site(p.DestinationId)||!Site(p.SiteId)||p.State is not ("Packing" or "Outbound" or "AtSite" or "Returning" or "Returned" or "Cancelled" or "Stranded")||p.Members==null||p.Members.Count is <1 or >8||p.Members.Distinct().Count()!=p.Members.Count||p.Members.Any(id=>!Colony.People.ContainsKey(id))||p.HomeCells==null||p.Members.Any(id=>!p.HomeCells.TryGetValue(id,out int cell)||!Cell(cell))||!Cargo(p.Cargo)||p.Cargo.Values.Sum()+(p.Artifacts?.Count??0)>p.Members.Count*40||p.Artifacts==null||p.Artifacts.Distinct().Count()!=p.Artifacts.Count||p.Artifacts.Any(id=>!r.Artifacts.Any(a=>a.Id==id&&a.PartyId==p.Id&&a.Custody=="Party"))||p.Route==null||p.Route.Any(i=>i<0||i>=144)||p.RouteIndex<0||p.RouteIndex>p.Route.Count||p.NextAt<0||p.FoodUsed<0)throw new InvalidDataException("Invalid expedition route/cargo/party.");if(p.State is "Packing" or "Outbound" or "AtSite" or "Returning")foreach(long id in p.Members)if(!activeMembers.Add(id))throw new InvalidDataException("Resident assigned to multiple expeditions.");if(p.State is "Outbound" or "Returning" or "Stranded")absent.UnionWith(p.Members);}
  if(!absent.SetEquals(r.Absent))throw new InvalidDataException("Absent resident set does not match traveling parties.");
  foreach(var t in r.Treaties){Id(t.Id);if(!Faction(t.FactionId)||!TreatyKinds.Contains(t.Kind)||t.SignedAt<0||t.SignedAt>Tick||t.DueAt<0||t.Payment is <0 or >3)throw new InvalidDataException("Invalid treaty terms.");}if(r.Treaties.Where(t=>t.Active).Select(t=>(t.FactionId,t.Kind)).Distinct().Count()!=r.Treaties.Count(t=>t.Active))throw new InvalidDataException("Duplicate active treaty.");
  foreach(var q in r.Quests){Id(q.Id);if(!Faction(q.FactionId)||!Site(q.SiteId)||!Artifact(q.ArtifactId)||q.Kind is not ("Recovery" or "Aid" or "Survey")||q.Status is not ("Offered" or "Accepted" or "Declined" or "Completed" or "Failed")||q.Deadline<0||!Cargo(q.Reward))throw new InvalidDataException("Invalid regional quest.");}
  foreach(var t in r.Traders){Id(t.Id);if(!Faction(t.FactionId)||t.State is not ("Traveling" or "Visiting" or "Returned")||t.ArrivesAt<0||t.LeavesAt<t.ArrivesAt||!Cargo(t.Cargo)||t.MarkerId<0||t.MarkerId>=NextEntityId||t.State=="Visiting"&&Find(t.MarkerId)==null)throw new InvalidDataException("Invalid visiting trader.");}
  foreach(var h in r.History){Id(h.Id);if(h.Tick<0||h.Tick>Tick||!Faction(h.FactionId)||!Site(h.SiteId)||!Artifact(h.ArtifactId)||h.PersonId!=0&&!r.People.Any(p=>p.Id==h.PersonId)||h.LocalActorId<0||h.LocalActorId>=NextEntityId||h.Text==null||h.Text.Length>512)throw new InvalidDataException("Invalid linked chronicle.");}
 }
}
